function formatBankLabel(n){return n.autoBoot?"* "+n.name+" *":n.name}function buildBankRow(n,t,i){const r=formatBankLabel(i);return'<p><div class="grid"><a role="button" href="javascript:void(0)" onclick="'+n+'">'+r+'<\/a><a role="button" class="secondary outline" href="javascript:void(0)" onclick="'+t+'">Safe Mode<\/a><a role="button" class="secondary" href="javascript:void(0)" onclick="toggleAutoBoot('+i.id+","+i.category+')">Toggle Auto Boot<\/a><\/div><\/p>'}async function getBankInfo(){await Promethe.api("bankinfo.json").then(async function(n){const t=await n.json();let i="";for(let n=0;n<t.length;n++)t[n].slots>0&&(t[n].category==0?i+=buildBankRow("launchBank("+t[n].id+")","launchBank("+t[n].id+", true)",t[n]):t[n].category==1?i+=buildBankRow("launchTsop()","launchTsop(true)",t[n]):t[n].category==2?i+=buildBankRow("launchRecovery()","launchRecovery(true)",t[n]):t[n].category==3&&(i+=buildBankRow("launchSdCard()","launchSdCard(true)",t[n])));document.getElementById("content").innerHTML=i}).catch(function(){document.getElementById("content").innerHTML="Failed to connect."})}async function toggleAutoBoot(n,t){await Promethe.api("toggleautoboot?"+n+","+t).then(function(n){n.status==200?(getBankInfo(),Promethe.toast("Auto boot updated.","success")):Promethe.toast("Failed to toggle auto boot.","error")}).catch(function(){Promethe.toast("Failed to connect.","error")})}async function launchBank(n,t){const i=t?n+",1":String(n);await Promethe.api("launchbank?"+i).then(function(n){n.status==200?(document.getElementById("content").innerHTML=t?"Launching in safe mode...":"Launching...",Promethe.toast("Launch command sent.","success")):Promethe.toast("Failed to launch.","error")}).catch(function(){Promethe.toast("Failed to connect.","error")})}async function launchTsop(n){const t=n?"1":"";await Promethe.api("launchtsop"+(t?"?"+t:"")).then(function(t){t.status==200?(document.getElementById("content").innerHTML=n?"Launching TSOP in safe mode...":"Launching TSOP...",Promethe.toast("Launch command sent.","success")):Promethe.toast("Failed to launch.","error")}).catch(function(){Promethe.toast("Failed to connect.","error")})}async function launchRecovery(n){const t=n?"1":"";await Promethe.api("launchrecovery"+(t?"?"+t:"")).then(function(t){t.status==200?(document.getElementById("content").innerHTML=n?"Launching recovery in safe mode...":"Launching recovery...",Promethe.toast("Launch command sent.","success")):Promethe.toast("Failed to launch.","error")}).catch(function(){Promethe.toast("Failed to connect.","error")})}async function launchSdCard(n){const t=n?"1":"";await Promethe.api("launchsdcard"+(t?"?"+t:"")).then(function(t){t.status==200?(document.getElementById("content").innerHTML=n?"Launching sdcard in safe mode...":"Launching sdcard...",Promethe.toast("Launch command sent.","success")):Promethe.toast("Failed to launch.","error")}).catch(function(){Promethe.toast("Failed to connect.","error")})}window.onload=function(){document.getElementById("year").textContent=(new Date).getFullYear();getBankInfo()};